'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var floor = require( '@stdlib/math/base/special/floor' );
var pow = require( '@stdlib/math/base/special/pow' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dgelqf = require( './../lib/dgelqf.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} N - matrix dimension
* @returns {Function} benchmark function
*/
function createBenchmark( order, N ) {
	var LWORK = N * 32;
	var work = new Float64Array( N );
	var TAU = new Float64Array( N );
	var A = discreteUniform( N*N, 1.0, 10.0, opts );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;
		var z;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dgelqf( order, N, N, A, N, TAU, work, LWORK );
			if ( z !== 0 ) {
				b.fail( 'should return 0' );
			}
		}
		b.toc();

		if ( z !== 0 ) {
			b.fail( 'should return 0' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var ord;
	var N;
	var f;
	var i;
	var k;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( i = min; i <= max; i++ ) {
			N = floor( pow( pow( 10, i ), 1.0/3.0 ) );
			f = createBenchmark( ord, N );
			bench( format( '%s::square_matrix:order=%s,size=%d', pkg, ord, N*N ), f );
		}
	}
}

main();
